    if text_lower.startswith("pass"):
        return 1
    if text_lower.startswith("fail"):
        return 0
    # Strong fail signal: traceback
    if "traceback (most recent call last)" in text_lower:
        return 0
    if "traceback(mostrecentcalllast)" in text_lower.replace(" ", ""):
        return 0
    # Count pytest-style PASSED/FAILED markers
    n_passed = text_lower.count(" passed") + text_lower.count("\npassed")
    n_failed = text_lower.count(" failed") + text_lower.count("\nfailed")
    n_error = text_lower.count("error:") + text_lower.count("error\n")
    if n_failed > 0 or n_error > 0:
        return 0
    if n_passed > 0:
        return 1
    # Keyword fallback (more conservative)
    fail_kw = ["traceback", "exception", "failures", "errors"]
    pass_kw = ["passed", "success", "completed"]
    has_fail = any(p in text_lower for p in fail_kw)
    has_pass = any(p in text_lower for p in pass_kw)
    if has_fail and not has_pass:
        return 0
    if has_pass and not has_fail:
        return 1
    return -1


